-- aar/w3/aar_row_636_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 636 (the Wall manual's AAR section requires the comparison with the previous report and the judges' reasoning) and its ask_aar_builders row.
-- Every value is from W3's own write call (the_wall_manual v20, log row 17, audit 42174), Wall 11994, 11999, 12007, 12015, 12023, 12036 and the readback post, the card in W3's thread, and md5sum by W3 of the files named.
-- The operator's words are as relayed to W3 by the coordinator; W3 did not read them in the project chat.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (636, '0', $t$ASK 636: the Wall manual requires every run AAR to be compared with the report before it and to list the issues in the judges' reasoning$t$,
  $t$The Wall manual's AAR section (7.4) asked for one DEFECTS list and did not ask for the run's cost, for a comparison with the report before it, or for the judges' reasoning. Change, in section 7.4 only: the RUN line carries the run's cost; the report is in short plain lines with no reading notes, sources or revision history; before it is written the previous run's report is read whole and every defect, suggested improvement and question in it is listed; DEFECTS is replaced by IMPROVEMENTS SINCE THE LAST RUN, DEFECTS NOT RESOLVED, NEW DEFECTS and STATUS OF ALL OBSERVATIONS (with fixed marks; an item not FIXED, DENIED, CLOSED or ANSWERED is carried into the next report); a JUDGES' REASONING part follows REVIEWS, in which a line against a drift guard is marked PANEL MEASURE and is not a fault, and the judgment of every seat that sat is read whole and named. Expected effect: every run AAR from now reports what improved, what is still open and the state of every earlier observation, and names the faults in the judges' reasoning.$t$,
  'in part',
  $t$Written by W3 at 06:32 CST 2026-11-25 on the operator's press "Write it" on W3's card: the_wall_manual version 19 (3ea921ffdf14c0b8dd73bd5fc1c6af55, 10,968 characters) to version 20 (3fddfa284698997506798a0d4142ab18, 12,507), four literal replacements, each old text found once, with its the_wall_manual_log row 17 and audit 42174 (Wall 12036). Read back PASS by W1 (Wall 12037: version 20 is 12,507 characters with md5 3fddfa28, equal to W1's reproduction of draft 4; W1 did not check log row 17 or audit 42174). One sentence was deleted ("DEFECTS: each defect found, in plain words, with the seat or outside read that found it.") and replaced by the four comparison items; two sentences were changed; one item was added. IN PART: the rule is written, and the comparison AAR of run 42528 was written to it before the write (W1, Wall 12023: its header meets the draft 4 text), but no run has been made since, so no AAR has yet been drafted under the written rule from the start. Four drafts: draft 1 answered the operator's words of 05:53 CST; draft 2 applied W1's N1 (the status marks); draft 3 added the JUDGES' REASONING item after his words of 06:06 CST; draft 4 applied W1's N1 on draft 3 (the judgment of every seat that sat is read whole and named). W3's mistake reported at the time: Wall 11991 was posted without re-reading the newest posts. Open: the next run's AAR.$t$,
  '11994, 11999, 12007, 12015, 12023, 12036, 12037',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$As relayed to W3 by the coordinator. 05:16 CST 2026-11-25: "why didn't you add the cost to the AAR. all i see is padding". 05:53 CST: "your AAR was horrible. you need to look at the past AAR to see what the defects were... report on the improvements from the last run... report on the defects that were not resolved... reported on new defects.... report status of all observations... update AAR manual requirements". 06:06 CST: "Also, your AAR should include issues found in the judge's reasoning. Make that a requirement in the AAR. Make sure that that's in the manual." Then W3's write card (cmsg_017ZQamDMHrS6fqMHnQDVo58QH7ABSvYB4bexeyiLHAdxr, "Write the new AAR rule (ASK 636) into the Wall manual now?"): he pressed "Write it" at 06:32 CST 2026-11-25.$t$::text),
  $j${"answer": "Write it", "question": "Write the new AAR rule (ASK 636) into the Wall manual now?", "options": ["Write it", "Hold"], "thread": "W3", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58QH7ABSvYB4bexeyiLHAdxr", "press_time": "06:32 CST 2026-11-25", "exact_text_message": "cmsg_017ZQamDMHrS6fqMHnQDVo585HL5DC2FeZnYfAzcq6MKb6", "source": "W3's own card and the press delivered to W3's thread."}$j$::jsonb,
  'W3',
  $j${"md5": "74aa463b41836f2c776d622f067ce165", "path": "ask636/w3/wm_pairs_636_draft4.json", "note": "no separate plan file: the four pairs are the plan and the change. Drafts 1 to 3: f4475cc9f7a90e77d4fcee644cab01e3, 5445e2c10ed9aa02f9204741e4364e94, 6adf504bb9402d488c7d03d1e59ffdbd.", "source": "md5sum by W3"}$j$::jsonb,
  $j$[{"path": "ask636/w3/wm_pairs_636_draft4.json", "md5": "74aa463b41836f2c776d622f067ce165", "what": "the four old and new texts written (commit 4ce7eb25)"}]$j$::jsonb,
  $j${"wall_manual": "the_wall_manual is versioned and rows are immutable; version 19 stands unchanged as its own row. Undo is a version 21 holding the version 19 text, on the operator's word.", "engine": "not written; nothing to revert", "rehearsed": "the four replacements were previewed on version 19 by W3 and reproduced by W1 (Wall 12015) before the card", "source": "W3's write call; Wall 12015"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (pairs draft 1)", "wall_id": 11994, "md5_graded": "f4475cc9", "verdict_norm": "PASS", "source": "Wall 11994"}, {"seat": "W1", "verdict": "PASS (pairs draft 2)", "wall_id": 11999, "md5_graded": "5445e2c1", "verdict_norm": "PASS", "source": "Wall 11999"}, {"seat": "W1", "verdict": "PASS WITH N1 (pairs draft 3)", "wall_id": 12007, "md5_graded": "6adf504b", "verdict_norm": "PASS", "source": "Wall 12007"}, {"seat": "W1", "verdict": "PASS (pairs draft 4)", "wall_id": 12015, "md5_graded": "74aa463b", "verdict_norm": "PASS", "source": "Wall 12015"}]$j$::jsonb,
  ARRAY['3fddfa284698997506798a0d4142ab18'], '[42174]'::jsonb,
  $j$[{"kind": "table row", "name": "the_wall_manual, section 7.4", "before": "version 19, md5 3ea921ffdf14c0b8dd73bd5fc1c6af55, 10,968 characters", "after": "version 20, md5 3fddfa284698997506798a0d4142ab18, 12,507 characters (+1,539); the_wall_manual_log row 17"}]$j$::jsonb,
  $j$[{"name": "Preview of the four replacements on version 19", "result": "each old text found once; result 12,507 characters, md5 3fddfa28; reproduced by W1", "source": "Wall 12015"}, {"name": "Checks inside the write call", "result": "pairs md5, base version 19 md5, each old text found once, result md5 and length, no launch since odv1_launches id 104: all passed, or the call would have raised", "source": "W3's write call"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "Read back PASS by W1 (Wall 12037: version 20 is 12,507 characters with md5 3fddfa28, equal to W1's reproduction of draft 4; W1 did not check log row 17 or audit 42174).", "wall_id": 12037, "source": "Wall 12037"}]$j$::jsonb,
  $j${"case": "NO RUN SINCE THE WRITE.", "runs": [], "mark_for_the_next_run": "the next run's AAR opens its RUN line with the cost and carries the parts IMPROVEMENTS SINCE THE LAST RUN, DEFECTS NOT RESOLVED, NEW DEFECTS, STATUS OF ALL OBSERVATIONS and JUDGES' REASONING, with every judgment read whole and named.", "not_shown": "an AAR drafted under the written rule from the start.", "source": "the_wall_manual version 20, section 7.4"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "none", "wall_manual": "WRITTEN: version 20, md5 3fddfa284698997506798a0d4142ab18, 12,507 characters, log row 17, audit 42174 (this row's own change)."}$j$::jsonb,
  'read back', $j$[11994, 11999, 12007, 12015, 12023, 12036, 12037]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W3'], $j$[{"seat": "W3", "what": "drafted the four pairs and wrote the_wall_manual version 20 on the operator's card", "wall_id": 12036}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
